// Mapea 'Punto de venta' -> API key del local (Módulo de stock centralizado)
const KEYS = {
  'Fábrica - Dean Funes 1258': 'PEGAR_API_KEY_FABRICA',
  'Fisherton - Eva Perón 7790': 'PEGAR_API_KEY_FISHERTON',
  'Norte - Alberdi 608 bis': 'PEGAR_API_KEY_NORTE',
}

const row = $input.item.json
const puntoDeVenta = String(row['Punto de venta'] || '').trim()
const tipo = String(row['Tipo'] || '').trim().toUpperCase()
const apiKey = KEYS[puntoDeVenta]

let _error = null
if (!apiKey) _error = `Punto de venta desconocido: "${puntoDeVenta}"`
else if (!['VENTA', 'INGRESO', 'AJUSTE'].includes(tipo)) _error = `Tipo inválido: "${tipo}"`

return {
  json: {
    ...row,
    apiKey: apiKey || '',
    tipoPath: tipo ? tipo.toLowerCase() : '',
    _error,
  },
}

const item = $('Armar pedido').item.json

if (item._error) {
  return { json: { ...item } }
}

const productos = ($input.item.json && $input.item.json.data) || []
const nombreBuscado = String(item['Producto'] || '').trim().toLowerCase()
const producto = productos.find(p => p.nombre.trim().toLowerCase() === nombreBuscado) || productos[0]

if (!producto) {
  return { json: { ...item, _error: `Producto no encontrado: "${item['Producto']}"` } }
}

const body = {
  productoId: producto.id,
  talle: String(item['Talle'] || '').trim(),
}
if (item['Color']) body.color = String(item['Color']).trim()

if (item.tipoPath === 'ajuste') {
  body.cantidadFinal = Number(item['Cantidad final (solo AJUSTE)'])
  body.nota = item['Nota'] || ''
} else {
  body.cantidad = Number(item['Cantidad'])
  if (item['Nota']) body.nota = item['Nota']
}

return { json: { ...item, body } }

const previo = $('Elegir producto y armar body').item.json._error || $('Armar pedido').item.json._error
const resp = $input.item.json

// El detalle del error puede venir de varias formas según cómo falle el HTTP.
function detalleError(r) {
  if (!r) return 'sin respuesta del servidor'
  return r.mensaje
    || r.message
    || r.error?.mensaje
    || r.error?.message
    || (typeof r.error === 'string' ? r.error : null)
    || JSON.stringify(r).slice(0, 200)
}

let estado
if (previo) {
  estado = `ERROR: ${previo}`
} else if (resp && resp.ok) {
  const stock = resp.stockRestante ?? resp.stockActual ?? ''
  estado = `OK — stock actual: ${stock}`
} else {
  estado = `ERROR: ${detalleError(resp)}`
}

return {
  json: {
    row_number: $('Nueva fila en Sheets').item.json.row_number,
    estado,
  },
}
